test_suite:
function createStore<T>(initial: T) {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    subscribe: (cb: () => void) => { listeners.add(cb); return () => listeners.delete(cb); },
    getSnapshot: () => value,
    set: (next: T) => { value = next; listeners.forEach(cb => cb()); },
  };
}

test('returns initial snapshot value', () => {
  const store = createStore(42);
  const { result } = renderHook(() => useSyncStore(store));
  expect(result.current).toBe(42);
});

test('re-renders when store notifies', () => {
  const store = createStore(0);
  const { result } = renderHook(() => useSyncStore(store));
  act(() => store.set(99));
  expect(result.current).toBe(99);
});

test('works with string values', () => {
  const store = createStore('hello');
  const { result } = renderHook(() => useSyncStore(store));
  act(() => store.set('world'));
  expect(result.current).toBe('world');
});

test('returns correct value after multiple updates', () => {
  const store = createStore(0);
  const { result } = renderHook(() => useSyncStore(store));
  act(() => store.set(1));
  act(() => store.set(2));
  act(() => store.set(3));
  expect(result.current).toBe(3);
});

