solution:
import { useSyncExternalStore } from 'react';

interface Store<T> {
  subscribe: (callback: () => void) => () => void;
  getSnapshot: () => T;
}

export function useSyncStore<T>(store: Store<T>): T {
  return useSyncExternalStore(store.subscribe, store.getSnapshot);
}
